import { getBetterAuthInternalAdapter, getBetterAuthSync, } from "../server/better-auth-instance.js";
import { getUserSetting, mutateUserSetting, } from "../settings/user-settings.js";
import { isGoogleProfileImageUrl } from "../shared/google-profile-image.js";
import { normalizeOnboardingRole, normalizeUserProfileName, resolveUserProfileName, USER_PROFILE_SETTING_KEY, } from "./shared.js";
async function getAuthUser(email) {
    if (!getBetterAuthSync())
        return null;
    const adapter = await getBetterAuthInternalAdapter().catch(() => undefined);
    if (!adapter)
        return null;
    return adapter.findUserByEmail(email, { includeAccounts: false });
}
function profileFromAuthUser(email, user) {
    const image = isGoogleProfileImageUrl(user.image)
        ? user.image.trim()
        : undefined;
    const onboardingRole = normalizeOnboardingRole(typeof user.onboardingRole === "string" ? user.onboardingRole : null);
    return {
        email,
        name: normalizeUserProfileName(user.name, email),
        ...(image ? { image } : {}),
        onboardingRole,
    };
}
async function profileFromAuthUserWithStoredName(email, user) {
    const profile = profileFromAuthUser(email, user);
    const storedResult = (await Promise.allSettled([getStoredUserProfile(email)]))[0];
    if (storedResult.status !== "fulfilled")
        return profile;
    return {
        ...profile,
        name: normalizeUserProfileName(resolveUserProfileName(email, storedResult.value.name, user.name), email),
        onboardingRole: profile.onboardingRole ?? storedResult.value.onboardingRole ?? null,
    };
}
async function getStoredUserProfile(email) {
    const stored = await getUserSetting(email, USER_PROFILE_SETTING_KEY);
    const storedName = typeof stored?.name === "string" ? stored.name : null;
    const name = resolveUserProfileName(email, storedName);
    const onboardingRole = normalizeOnboardingRole(typeof stored?.onboardingRole === "string" ? stored.onboardingRole : null);
    return {
        email,
        name: normalizeUserProfileName(name, email),
        onboardingRole,
    };
}
async function updateFallbackUserProfile(email, updates) {
    await mutateUserSetting(email, USER_PROFILE_SETTING_KEY, (current) => ({
        ...(current ?? {}),
        ...updates,
    }));
}
export async function getUserProfile(email) {
    const authUser = await getAuthUser(email);
    if (authUser)
        return profileFromAuthUserWithStoredName(email, authUser.user);
    return getStoredUserProfile(email);
}
export async function getUserProfiles(emails) {
    const uniqueEmails = Array.from(new Set(emails
        .map((email) => email.trim())
        .filter(Boolean)
        .map((email) => email.toLowerCase())));
    if (uniqueEmails.length === 0)
        return new Map();
    const adapter = getBetterAuthSync()
        ? await getBetterAuthInternalAdapter().catch(() => undefined)
        : undefined;
    const profiles = new Map();
    let batchLookupSucceeded = false;
    if (adapter?.listUsers) {
        try {
            const users = await adapter.listUsers(uniqueEmails.length, undefined, undefined, [
                {
                    field: "email",
                    operator: "in",
                    value: uniqueEmails,
                    mode: "insensitive",
                },
            ]);
            const userProfiles = await Promise.all(users.map(async (user) => {
                const email = user.email.trim().toLowerCase();
                return email
                    ? [
                        email,
                        await profileFromAuthUserWithStoredName(email, user),
                    ]
                    : null;
            }));
            for (const entry of userProfiles) {
                if (entry)
                    profiles.set(...entry);
            }
            batchLookupSucceeded = true;
        }
        catch {
            // coercion-ok: older or custom adapters use the established per-user fallback.
            // Fall back to the single-profile path for older/custom adapters.
        }
    }
    const missingEmails = uniqueEmails.filter((email) => !profiles.has(email));
    const results = await Promise.allSettled(missingEmails.map(async (email) => [
        email,
        batchLookupSucceeded
            ? await getStoredUserProfile(email)
            : await getUserProfile(email),
    ]));
    for (const result of results) {
        if (result.status === "fulfilled")
            profiles.set(...result.value);
    }
    return profiles;
}
export async function updateUserProfile(email, name, onboardingRole) {
    const normalizedName = normalizeUserProfileName(name, email);
    const normalizedOnboardingRole = onboardingRole === undefined
        ? undefined
        : normalizeOnboardingRole(onboardingRole);
    const authUser = await getAuthUser(email);
    const adapter = authUser
        ? await getBetterAuthInternalAdapter().catch(() => undefined)
        : undefined;
    if (normalizedOnboardingRole !== undefined) {
        if (authUser?.user.id && adapter?.updateUser) {
            await adapter.updateUser(authUser.user.id, {
                name: normalizedName,
                onboardingRole: normalizedOnboardingRole,
            });
            const saved = await getAuthUser(email);
            const savedRole = normalizeOnboardingRole(typeof saved?.user.onboardingRole === "string"
                ? saved.user.onboardingRole
                : null);
            if (savedRole !== normalizedOnboardingRole) {
                throw new Error("Failed to save onboarding role on the Better Auth user row.");
            }
        }
        else {
            await updateFallbackUserProfile(email, {
                name: normalizedName,
                onboardingRole: normalizedOnboardingRole,
            });
        }
        return {
            email,
            name: normalizedName,
            onboardingRole: normalizedOnboardingRole,
        };
    }
    else if (authUser?.user.id && adapter?.updateUser) {
        await adapter.updateUser(authUser.user.id, { name: normalizedName });
    }
    else {
        await updateFallbackUserProfile(email, {
            name: normalizedName,
        });
    }
    const profile = await getUserProfile(email);
    return { ...profile, name: normalizedName };
}
export async function updateUserOnboardingRole(email, onboardingRole) {
    const normalizedOnboardingRole = normalizeOnboardingRole(onboardingRole);
    if (!normalizedOnboardingRole) {
        throw new Error("Cannot save an empty onboarding role.");
    }
    const authUser = await getAuthUser(email);
    const adapter = authUser
        ? await getBetterAuthInternalAdapter().catch(() => undefined)
        : undefined;
    if (!authUser?.user.id || !adapter?.updateUser) {
        await updateFallbackUserProfile(email, {
            onboardingRole: normalizedOnboardingRole,
        });
        return normalizedOnboardingRole;
    }
    await adapter.updateUser(authUser.user.id, {
        onboardingRole: normalizedOnboardingRole,
    });
    const saved = await getAuthUser(email);
    const savedRole = normalizeOnboardingRole(typeof saved?.user.onboardingRole === "string"
        ? saved.user.onboardingRole
        : null);
    if (savedRole !== normalizedOnboardingRole) {
        throw new Error("Failed to save onboarding role on the Better Auth user row.");
    }
    return normalizedOnboardingRole;
}
